package com.aoo.bcg.poker;
import org.junit.jupiter.api.Test;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class PaoDeKuaiRuleSetTest{@Test void recognizesRegionalCombinationsAndGuardsFirstAndReportedSingle(){var config=new PaoDeKuaiConfig(5,true,true,true,103,true);var rules=new PaoDeKuaiRuleSet(config);assertEquals("CONSECUTIVE_PAIRS",rules.recognize(List.of(103,203,104,204),null).type());assertEquals("AIRPLANE_WITH_SINGLES",rules.recognize(List.of(103,203,303,104,204,304,105,106),null).type());assertEquals("FOUR_WITH_TWO",rules.recognize(List.of(107,207,307,407,108,109),null).type());var state=new PokerTurnState(java.util.Map.of(0,List.of(103,104),1,List.of(105)),0,null,-1,java.util.Set.of(),false,-1);var engine=new PaoDeKuaiEngine();assertThrows(IllegalStateException.class,()->engine.play(state,0,List.of(104),rules,new PaoDeKuaiContext(true,3,state.hands().get(0))));assertThrows(IllegalStateException.class,()->rules.validatePlay(List.of(103),new PaoDeKuaiContext(false,1,List.of(103,114))));}}
